Definition rsA_W (lo : Z) (sp : word) (stb ff : Z) : list (Z * Z) :=
  [(ff, ff + 64); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 8); (lo, bv_unsigned sp);
   (stb + 104, stb + 144); (stb + 264, stb + 272)]%Z.

Section HCW.
  Context {HCEIL : HeapCeil}.
